//! Parity of `gsd-envelope` with the Python oracle, over `tests/vectors/envelope.json`.
//!
//! The vector file is generated by `tests/parity/gen_envelope_vectors.py` from the real `swarm/envelope.py`: its canonical form,
//! `sign_envelope` (signature, dev-key audit flag and fail-closed message), `verify_envelope` and the key precedence, each under a
//! controlled environment. Test keys are derived at run time from the documented phrase `KEY_PHRASE` (a key written `@label` is
//! `sha256(KEY_PHRASE + label)` in hex); the file holds public keys and signatures only.
//!
//! A vector marked `"rust": "declined"` is one the crate must refuse so that Python answers; the tests pin each such refusal so a
//! change in what Rust answers is a visible decision.

use std::collections::HashMap;
use std::ffi::OsString;
use std::fs;
use std::os::unix::fs::symlink;
use std::path::{Path, PathBuf};

use gsd_envelope::{
    canonical_bytes, conventional_key_file_presence, parse_envelope, sign_envelope,
    verify_envelope, Declined, KeyFilePresence, KeyMaterial, ParsedEnvelope, SignError,
};
use gsd_route::{obj_get, parse_json, Json};
use sha2::{Digest, Sha256};

/// The documented phrase of the vector generator; the vector file repeats it and a test checks they agree.
const KEY_PHRASE: &str =
    "agent-swarm gsd-envelope test vectors: derived key phrase, not a secret: ";

type TestResult = Result<(), String>;

fn vectors() -> Result<Json, String> {
    parse_json(include_str!("vectors/envelope.json")).map_err(|e| e.message().to_string())
}

fn member<'a>(value: &'a Json, key: &str) -> Result<&'a Json, String> {
    match value {
        Json::Obj(fields) => obj_get(fields, key).ok_or_else(|| format!("missing member {key}")),
        _ => Err(format!("not an object while looking for {key}")),
    }
}

fn text<'a>(value: &'a Json, key: &str) -> Result<&'a str, String> {
    match member(value, key)? {
        Json::Str(text) => Ok(text),
        _ => Err(format!("{key} is not a string")),
    }
}

fn section<'a>(vectors: &'a Json, key: &str) -> Result<&'a [Json], String> {
    match member(vectors, key)? {
        Json::Arr(items) => Ok(items),
        _ => Err(format!("{key} is not an array")),
    }
}

/// Resolves a vector value: `@label[|transform...]` derives a key, `@dev` is the public dev key, anything else is literal.
fn key_value(spec: &str, dev_key: &str) -> Result<String, String> {
    let Some(rest) = spec.strip_prefix('@') else {
        return Ok(spec.to_string());
    };
    let mut parts = rest.split('|');
    let label = parts.next().unwrap_or_default();
    let mut value = if label == "dev" {
        dev_key.to_string()
    } else {
        hex::encode(Sha256::digest(format!("{KEY_PHRASE}{label}").as_bytes()))
    };
    for transform in parts {
        value = match transform {
            "upper" => value.to_uppercase(),
            "spaced" => value
                .as_bytes()
                .chunks(2)
                .map(|pair| String::from_utf8_lossy(pair).into_owned())
                .collect::<Vec<_>>()
                .join(" "),
            "nl" => format!("{value}\n"),
            "innerspace" => format!("{} {}", &value[..1], &value[1..]),
            "trunc" => value[..value.len() - 2].to_string(),
            "long" => value.repeat(10),
            "short" => value[..3].to_string(),
            "uni" => format!("{value}-\u{e9}\u{65e5}"),
            other => return Err(format!("unknown transform {other}")),
        };
    }
    Ok(value)
}

/// A fresh directory holding one layout vector's file system, removed when dropped. Its path is canonical, so no ancestor above it
/// is a symlink and the layout alone decides what the conventional path walk finds.
struct LayoutRoot(PathBuf);

impl LayoutRoot {
    /// Builds the `["dir", path]`, `["file", path]` and `["symlink", path, target]` operations of a vector under a new directory
    /// of the test target directory (`{root}` in a symlink target is that directory).
    fn build(index: usize, operations: &Json) -> Result<Self, String> {
        let base = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!(
            "gsd-envelope-layout-{}-{index}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&base);
        fs::create_dir_all(&base).map_err(|e| e.to_string())?;
        let root = Self(fs::canonicalize(&base).map_err(|e| e.to_string())?);
        let Json::Arr(operations) = operations else {
            return Err("layout is not an array".to_string());
        };
        for operation in operations {
            let Json::Arr(parts) = operation else {
                return Err("layout operation is not an array".to_string());
            };
            let words: Vec<&str> = parts
                .iter()
                .map(|part| match part {
                    Json::Str(word) => Ok(word.as_str()),
                    _ => Err("layout operation holds a non-string".to_string()),
                })
                .collect::<Result<_, _>>()?;
            let done = match words.as_slice() {
                ["dir", path] => fs::create_dir_all(root.0.join(path)),
                ["file", path] => fs::write(root.0.join(path), "placeholder text, not a key\n"),
                ["symlink", path, target] => symlink(
                    target.replace("{root}", &root.0.display().to_string()),
                    root.0.join(path),
                ),
                other => return Err(format!("unknown layout operation {other:?}")),
            };
            done.map_err(|e| format!("{words:?}: {e}"))?;
        }
        Ok(root)
    }
}

impl Drop for LayoutRoot {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

/// The key material the oracle saw for a vector's environment. `{root}` in a value is the layout directory; a JSON `null` leaves
/// the variable unset. The conventional key file is classified on the real file system.
fn keys_for(
    case: &Json,
    dev_key: &str,
    root: Option<&Path>,
) -> Result<Result<KeyMaterial, Declined>, String> {
    let Json::Obj(vars) = member(case, "env")? else {
        return Err("env is not an object".to_string());
    };
    let root_text = root.map(|path| path.display().to_string());
    let mut map: HashMap<String, OsString> = HashMap::new();
    for (name, value) in vars {
        let spec = match value {
            Json::Str(spec) => spec,
            Json::Null => continue,
            _ => return Err(format!("env {name} is not a string or null")),
        };
        let spec = match &root_text {
            Some(root) => spec.replace("{root}", root),
            None => spec.clone(),
        };
        map.insert(name.clone(), OsString::from(key_value(&spec, dev_key)?));
    }
    Ok(KeyMaterial::from_lookup(
        |name| map.get(name).cloned(),
        conventional_key_file_presence,
    ))
}

/// Signs `body` and compares the outcome with the oracle's recorded one (signature and dev-key audit flag, or the fail-closed
/// text, with the envelope left unsigned). Returns whether the oracle signed.
fn assert_signing_matches(
    name: &str,
    keys: &KeyMaterial,
    mut envelope: ParsedEnvelope,
    python: &Json,
) -> Result<bool, String> {
    let outcome = sign_envelope(&mut envelope, keys);
    if matches!(member(python, "ok")?, Json::Bool(true)) {
        let outcome = outcome.map_err(|e| format!("{name}: {e}"))?;
        assert_eq!(
            text(envelope.as_json(), "sig")?,
            text(python, "sig")?,
            "{name}"
        );
        let audit = matches!(member(python, "dev_key_audit")?, Json::Bool(true));
        assert_eq!(outcome.dev_key_audit, audit, "{name}: dev-key audit flag");
        Ok(true)
    } else {
        let Err(SignError::Policy(error)) = outcome else {
            return Err(format!("{name}: expected the fail-closed error"));
        };
        assert_eq!(error.message(), text(python, "error")?, "{name}");
        assert!(
            matches!(envelope.as_json(), Json::Obj(fields) if obj_get(fields, "sig").is_none()),
            "{name}: nothing may be signed"
        );
        Ok(false)
    }
}

fn dev_key(vectors: &Json) -> Result<String, String> {
    Ok(text(vectors, "dev_key")?.to_string())
}

fn expects_decline(case: &Json) -> Result<bool, String> {
    match text(case, "rust")? {
        "declined" => Ok(true),
        "match" => Ok(false),
        other => Err(format!("unknown rust expectation {other}")),
    }
}

#[test]
fn the_vector_header_ties_the_test_keys_and_the_dev_key_to_the_oracle() -> TestResult {
    let vectors = vectors()?;
    assert_eq!(text(&vectors, "key_phrase")?, KEY_PHRASE);
    let dev = dev_key(&vectors)?;
    assert_eq!(
        hex::encode(Sha256::digest(dev.as_bytes())),
        text(&vectors, "dev_key_sha256")?
    );
    let Json::Obj(public_keys) = member(&vectors, "ed25519_public_keys")? else {
        return Err("public keys are not an object".to_string());
    };
    assert!(public_keys.len() >= 2);
    for (label, expected) in public_keys {
        let Json::Str(expected) = expected else {
            return Err("public key is not a string".to_string());
        };
        let seed = key_value(&format!("@{label}"), &dev)?;
        let map = HashMap::from([("SWARM_ED25519_KEY".to_string(), OsString::from(seed))]);
        let keys =
            KeyMaterial::from_lookup(|name| map.get(name).cloned(), |_| KeyFilePresence::Absent)
                .map_err(|e| e.to_string())?;
        assert_eq!(
            keys.ed25519_public_key().map(hex::encode).as_deref(),
            Some(expected.as_str()),
            "public key of {label}"
        );
    }
    Ok(())
}

#[test]
fn canonical_form_equals_the_oracles_bytes() -> TestResult {
    let vectors = vectors()?;
    let (mut matched, mut declined) = (0, 0);
    for case in section(&vectors, "canonical")? {
        let name = text(case, "name")?;
        let parsed = parse_envelope(text(case, "text")?);
        if expects_decline(case)? {
            assert!(parsed.is_err(), "{name}: Rust must decline");
            declined += 1;
            continue;
        }
        let Json::Str(expected) = member(case, "python")? else {
            return Err(format!(
                "{name}: the oracle raised but Rust is expected to match"
            ));
        };
        let envelope = parsed.map_err(|e| format!("{name}: {e}"))?;
        let bytes = canonical_bytes(&envelope).map_err(|e| format!("{name}: {e}"))?;
        assert_eq!(String::from_utf8_lossy(&bytes), expected.as_str(), "{name}");
        matched += 1;
    }
    assert!(
        matched >= 12 && declined >= 5,
        "{matched} matched, {declined} declined"
    );
    Ok(())
}

#[test]
fn signing_equals_the_oracle_for_every_key_environment() -> TestResult {
    let vectors = vectors()?;
    let dev = dev_key(&vectors)?;
    let (mut signed, mut refused, mut declined) = (0, 0, 0);
    for case in section(&vectors, "sign")? {
        let name = text(case, "name")?;
        let keys = keys_for(case, &dev, None)?;
        let body = parse_envelope(text(case, "body_text")?);
        if expects_decline(case)? {
            assert!(keys.is_err() || body.is_err(), "{name}: Rust must decline");
            declined += 1;
            continue;
        }
        let keys = keys.map_err(|e| format!("{name}: {e}"))?;
        let envelope = body.map_err(|e| format!("{name}: {e}"))?;
        if assert_signing_matches(name, &keys, envelope, member(case, "python")?)? {
            signed += 1;
        } else {
            refused += 1;
        }
    }
    assert!(
        signed >= 60 && refused >= 30 && declined >= 15,
        "{signed} signed, {refused} refused, {declined} declined"
    );
    Ok(())
}

#[test]
fn verification_equals_the_oracle_for_every_signature_shape() -> TestResult {
    let vectors = vectors()?;
    let dev = dev_key(&vectors)?;
    let (mut accepted, mut rejected, mut declined) = (0, 0, 0);
    for case in section(&vectors, "verify")? {
        let name = text(case, "name")?;
        let keys = keys_for(case, &dev, None)?.map_err(|e| format!("{name}: {e}"))?;
        let envelope = parse_envelope(text(case, "envelope_text")?);
        if expects_decline(case)? {
            assert!(envelope.is_err(), "{name}: Rust must decline");
            declined += 1;
            continue;
        }
        let envelope = envelope.map_err(|e| format!("{name}: {e}"))?;
        let expected = match member(case, "python")? {
            Json::Bool(value) => *value,
            other => return Err(format!("{name}: the oracle answered {other:?}")),
        };
        assert_eq!(verify_envelope(&envelope, &keys), expected, "{name}");
        if expected {
            accepted += 1;
        } else {
            rejected += 1;
        }
    }
    assert!(
        accepted >= 20 && rejected >= 100 && declined >= 3,
        "{accepted} accepted, {rejected} rejected, {declined} declined"
    );
    Ok(())
}

/// Compares the key-state answers of `keys` with the oracle's recorded `real_key_configured()`, `insecure_dev_key() is not None`
/// and `signing_config_error()`.
fn assert_key_state_matches(name: &str, keys: &KeyMaterial, state: &Json) -> TestResult {
    let flag = |key: &str| match member(state, key)? {
        Json::Bool(value) => Ok(*value),
        _ => Err(format!("{name}: {key} is not a boolean")),
    };
    assert_eq!(
        keys.real_key_configured(),
        flag("real_key_configured")?,
        "{name}: real_key_configured"
    );
    assert_eq!(
        keys.dev_key_active(),
        flag("dev_key_active")?,
        "{name}: dev_key_active"
    );
    let expected = match member(state, "config_error")? {
        Json::Null => None,
        Json::Str(message) => Some(message.as_str()),
        _ => return Err(format!("{name}: config_error is not text or null")),
    };
    assert_eq!(keys.config_error(), expected, "{name}: config_error");
    Ok(())
}

#[test]
fn real_key_dev_key_and_config_error_equal_the_oracle_for_every_combination() -> TestResult {
    let vectors = vectors()?;
    let dev = dev_key(&vectors)?;
    let mut checked = 0;
    for case in section(&vectors, "key_state")? {
        let name = text(case, "name")?;
        let keys = keys_for(case, &dev, None)?.map_err(|e| format!("{name}: {e}"))?;
        assert_key_state_matches(name, &keys, member(case, "python")?)?;
        checked += 1;
    }
    assert_eq!(
        checked, 48,
        "3 seeds x 4 secrets x opt-in x REQUIRE_KEY combinations"
    );
    Ok(())
}

/// F-1: the conventional key-file path. Each vector builds a file system layout, runs Python on it and records the outcome; the
/// class says whether Rust must match that outcome (`exact`) or must decline with a named reason (`decline`). Every declined
/// vector is one where Python's answer is a refusal, so a Rust answer there would be a signature or verification Python denies.
#[test]
fn the_conventional_key_path_follows_pythons_walk_or_declines() -> TestResult {
    let vectors = vectors()?;
    let dev = dev_key(&vectors)?;
    let (mut exact_signed, mut exact_refused) = (0, 0);
    let (mut declined_file, mut declined_path) = (0, 0);
    for (index, case) in section(&vectors, "conventional")?.iter().enumerate() {
        let name = text(case, "name")?;
        let root = LayoutRoot::build(index, member(case, "layout")?)?;
        let keys = keys_for(case, &dev, Some(&root.0))?;
        let python = member(case, "python")?;
        match text(case, "class")? {
            "exact" => {
                let keys = keys.map_err(|e| format!("{name}: {e}"))?;
                let body = parse_envelope(text(case, "body_text")?).map_err(|e| e.to_string())?;
                if assert_signing_matches(name, &keys, body, python)? {
                    exact_signed += 1;
                } else {
                    exact_refused += 1;
                }
                assert_key_state_matches(name, &keys, member(case, "key_state")?)?;
            }
            "decline" => {
                let (expected, count) = match text(case, "declined_as")? {
                    "ConventionalKeyFile" => (Declined::ConventionalKeyFile, &mut declined_file),
                    "ConventionalKeyPath" => (Declined::ConventionalKeyPath, &mut declined_path),
                    other => return Err(format!("{name}: unknown declined_as {other}")),
                };
                assert_eq!(keys.err(), Some(expected), "{name}");
                assert!(
                    matches!(member(python, "ok")?, Json::Bool(false)),
                    "{name}: Python must refuse where Rust declines"
                );
                *count += 1;
            }
            other => return Err(format!("{name}: unknown class {other}")),
        }
    }
    assert_eq!(
        (exact_signed, exact_refused, declined_file, declined_path),
        (48, 21, 9, 48),
        "exact signed, exact refused, declined for a present file, declined for an unclear path"
    );
    Ok(())
}

/// The review's item 10 vectors: crafted Ed25519 signatures (small-order or non-canonical R, wrong lengths) must not verify, and a
/// last base64 character with other unused bits must, because Python's decoder ignores those bits. The recorded Python answer is
/// asserted too, so the file cannot drift from the oracle unnoticed.
#[test]
fn crafted_ed25519_signatures_are_judged_as_python_judges_them() -> TestResult {
    let vectors = vectors()?;
    let dev = dev_key(&vectors)?;
    let (mut rejected, mut accepted) = (0, 0);
    for case in section(&vectors, "verify")? {
        let name = text(case, "name")?;
        let Some(label) = name.strip_prefix("ed25519_edge/") else {
            continue;
        };
        let keys = keys_for(case, &dev, None)?.map_err(|e| format!("{name}: {e}"))?;
        let envelope = parse_envelope(text(case, "envelope_text")?).map_err(|e| e.to_string())?;
        let verdict = verify_envelope(&envelope, &keys);
        let accepts = label.starts_with("extra_trailing_bits_");
        assert_eq!(verdict, accepts, "{name}: Rust");
        assert!(
            matches!(member(case, "python")?, Json::Bool(python) if *python == accepts),
            "{name}: Python"
        );
        if accepts {
            accepted += 1;
        } else {
            rejected += 1;
        }
    }
    assert_eq!(
        (rejected, accepted),
        (11, 15),
        "7 R encodings, 2 zero-S, 2 wrong lengths; 15 other spellings of the last character"
    );
    Ok(())
}

/// F-5 of the security review, recorded as a decision: Python verifies an `hmac:` signature while an Ed25519 signer is configured
/// and never downgrades an `ed25519:` signature. Rust matches it for parity; tightening needs a user decision.
#[test]
fn hmac_beside_an_ed25519_signer_is_pinned_as_pythons_behaviour() -> TestResult {
    let vectors = vectors()?;
    let dev = dev_key(&vectors)?;
    let expected = [
        ("f5_parity/hmac_signature_beside_an_ed25519_signer", true),
        (
            "f5_parity/hmac_signature_beside_a_malformed_ed25519_seed",
            true,
        ),
        (
            "f5_parity/ed25519_signature_is_not_downgraded_to_hmac",
            false,
        ),
    ];
    for (wanted, verdict) in expected {
        let case = section(&vectors, "verify")?
            .iter()
            .find(|case| text(case, "name").is_ok_and(|name| name == wanted))
            .ok_or_else(|| format!("{wanted} is missing from the vectors"))?;
        let keys = keys_for(case, &dev, None)?.map_err(|e| e.to_string())?;
        let envelope = parse_envelope(text(case, "envelope_text")?).map_err(|e| e.to_string())?;
        assert_eq!(verify_envelope(&envelope, &keys), verdict, "{wanted}: Rust");
        assert!(
            matches!(member(case, "python")?, Json::Bool(python) if *python == verdict),
            "{wanted}: Python"
        );
    }
    Ok(())
}
